                            },
                            body: JSON.stringify(this.studentFile.behaviorForm)
                        });
                        const json = await res.json();
                        if (res.ok) {
                            this.showToast('تم تسجيل المخالفة بنجاح');
                            this.studentFile.behaviorForm = { type: '', level: 'LOW', description: '' };
